html:
{% set rooms_data = frappe.get_all(
    "Floors And Rooms Master",
    fields=[
        "name",
        "floor",
        "rooms",
        "qr_checkin_data",
        "qr_checkout_data"
    ],
    order_by="floor asc, rooms asc",
    limit_page_length=0
) %}

{% set per_page = 4 %}

<style>
@import url('https://fonts.googleapis.com/css2?family=Prompt:wght@400;600;700&display=swap');

@page {
    size: A4 landscape;
    margin: 10mm;
}

* {
    font-family: 'Prompt', 'Noto Sans Thai', sans-serif !important;
    box-sizing: border-box;
}

html, body {
    margin: 0 !important;
    padding: 0 !important;
}

.print-format {
    width: 277mm !important;
    max-width: 277mm !important;
    min-height: 0 !important;
    padding: 0 !important;
    margin: 0 auto !important;
    background: #ffffff !important;
}

/* หน้ากระดาษ A4 แนวนอน */
.print-page {
    width: 277mm;
    height: 190mm;
    margin: 0 auto;
    padding: 0;
    overflow: hidden;
    page-break-after: always;
    break-after: page;
}

.print-page:last-child {
    page-break-after: auto;
    break-after: auto;
}

/* ตาราง 2 คอลัมน์ x 2 แถว */
.block-table {
    width: 100%;
    border-collapse: separate !important;
    border-spacing: 10mm 10mm !important;
    table-layout: fixed;
    margin: 0 !important;
}

.block-cell {
    width: 50%;
    height: 80mm;
    padding: 0 !important;
    vertical-align: middle !important;
    text-align: center !important;
}

/* กล่องนอก ขนาด 10.5 x 7.7 ซม. */
.room-block {
    width: 105mm !important;
    height: 77mm !important;
    min-width: 105mm !important;
    max-width: 105mm !important;
    min-height: 77mm !important;
    max-height: 77mm !important;
    border: 2px solid #000000;
    border-radius: 0;
    background: #ffffff;
    padding: 3mm;
    margin: 0 auto;
    position: relative;
    overflow: hidden;
}

/* โครงสร้างด้านใน */
.room-inner {
    width: 100%;
    height: 100%;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: flex-start;
}

/* ชื่อชั้นและห้องด้านบน */
.room-name-area {
    width: 100%;
    height: 10mm;
    display: flex;
    align-items: center;
    justify-content: center;
}

.room-header {
    writing-mode: horizontal-tb;
    text-orientation: mixed;
    transform: none;
    font-size: 13px;
    font-weight: 700;
    color: #111827;
    white-space: nowrap;
    text-align: center;
    line-height: 1.2;
}

/* พื้นที่ QR ทั้งสองใบ */
.qr-area {
    width: 100%;
    height: calc(100% - 10mm);
    display: flex;
    flex-direction: row;
    justify-content: space-evenly;
    align-items: center;
    gap: 2mm;
}

/* วาง CHECK-OUT และ CHECK-IN เคียงข้างกัน */
.qr-holder {
    width: 44mm;
    height: 56mm;
    display: flex;
    justify-content: center;
    align-items: center;
}

/* การ์ด QR */
.qr-card {
    width: 46mm;
    height: 55mm;
    padding: 1mm;
    border: 1px solid #e5e7eb;
    border-radius: 5px;
    background: #ffffff;

    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
    gap: 0.5mm;

    transform: none;
    transform-origin: center center;
    flex-shrink: 0;
}

/* หัวข้อ CHECK-IN / CHECK-OUT */
.qr-title {
    font-size: 9px;
    font-weight: 700;
    line-height: 1.1;
    white-space: nowrap;
    text-align: center;
    margin: 0;
}

.qr-title.checkin {
    color: #16a34a !important;
}

.qr-title.checkout {
    color: #dc2626 !important;
}

/* QR CODE ตั้งตรง อ่านจากซ้ายไปขวา */
.qr-image-wrapper {
    width: 45mm;
    height: 45mm;
    display: flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
}

.qr-image-wrapper img {
    display: block;
    width: 45mm !important;
    height: 45mm !important;
    max-width: none !important;
    object-fit: contain;
}

/* ข้อความใต้ QR */
.qr-footer-text {
    width: 100%;
    font-size: 7px;
    font-weight: 400;
    color: #6b7280;
    text-align: center;
    line-height: 1.1;
    overflow-wrap: anywhere;
}

/* ตั้งค่าสำหรับพิมพ์ */
@media print {

    html, body {
        margin: 0 !important;
        padding: 0 !important;
    }

    .print-format {
        width: 277mm !important;
        max-width: 277mm !important;
        padding: 0 !important;
        margin: 0 auto !important;
    }

    .print-page {
        width: 277mm !important;
        height: 190mm !important;
        page-break-after: always !important;
        break-after: page !important;
        page-break-inside: avoid !important;
        break-inside: avoid !important;
    }

    .print-page:last-child {
        page-break-after: auto !important;
        break-after: auto !important;
    }

    .block-table tr,
    .block-cell,
    .room-block {
        page-break-inside: avoid !important;
        break-inside: avoid !important;
    }

    .room-block,
    .qr-card,
    .qr-title {
        -webkit-print-color-adjust: exact !important;
        print-color-adjust: exact !important;
    }
}
</style>

{% if rooms_data %}

{% for start in range(0, rooms_data|length, per_page) %}

    {% set page_rooms = rooms_data[start:start + per_page] %}

    <div class="print-page">

        <table class="block-table">
            <tbody>

            {% for row_start in range(0, 4, 2) %}

                <tr>

                {% for col in range(2) %}

                    {% set idx = row_start + col %}

                    <td class="block-cell">

                    {% if idx < page_rooms|length %}

                        {% set room = page_rooms[idx] %}

                        <div class="room-block">

                            <div class="room-inner">

                                <!-- ชื่อชั้นและห้องด้านบน -->
                                <div class="room-name-area">
                                    <div class="room-header">
                                        {{ room.floor or '' }} - {{ room.rooms or '' }}
                                    </div>
                                </div>

                                <!-- QR CHECK-OUT และ CHECK-IN -->
                                <div class="qr-area">

                                    <!-- CHECK-OUT ด้านซ้าย -->
                                    <div class="qr-holder">
                                        <div class="qr-card">

                                            <div class="qr-title checkin">
                                                QR CHECK-IN 
                                            </div>

                                            <div class="qr-image-wrapper">

                                                {% if room.qr_checkin_data %}
                                                
                                                 <img
                                                        src="https://api.qrserver.com/v1/create-qr-code/?size=400x400&amp;margin=10&amp;data={{ room.qr_checkin_data | urlencode }}"
                                                        alt="QR Check-in"
                                                    >
                                                    
                                                {% else %}

                                                    <span style="font-size:8px;color:#999;">
                                                        ไม่มีข้อมูล
                                                    </span>

                                                {% endif %}

                                            </div>

                                            <div class="qr-footer-text">
                                                {{ room.floor or '' }} - {{ room.rooms or '' }}
                                            </div>

                                        </div>
                                    </div>

                                    <!-- CHECK-IN ด้านขวา -->
                                    <div class="qr-holder">
                                        <div class="qr-card">

                                            <div class="qr-title checkout">
                                                QR CHECK-OUT
                                            </div>

                                            <div class="qr-image-wrapper">

                                                {% if room.qr_checkout_data %}

                                                   
                                                    <img
                                                        src="https://api.qrserver.com/v1/create-qr-code/?size=400x400&amp;margin=10&amp;data={{ room.qr_checkout_data | urlencode }}"
                                                        alt="QR Check-out"
                                                    >

                                                {% else %}

                                                    <span style="font-size:8px;color:#999;">
                                                        ไม่มีข้อมูล
                                                    </span>

                                                {% endif %}

                                            </div>

                                            <div class="qr-footer-text">
                                                {{ room.floor or '' }} - {{ room.rooms or '' }}
                                            </div>

                                        </div>
                                    </div>

                                </div>

                            </div>

                        </div>

                    {% endif %}

                    </td>

                {% endfor %}

                </tr>

            {% endfor %}

            </tbody>
        </table>

    </div>

{% endfor %}

{% else %}

<div style="text-align:center;padding:20px;">
    ไม่พบข้อมูล QR Code
</div>

{% endif %}
